local ActivityMidFestivalRightNode = Class('ActivityMidFestivalRightNode')

--region lifecycle

function ActivityMidFestivalRightNode:__init()
    self.config = {
        ---@type MidFestivalMainQuestLevelVo
        vo = nil,
        ---@type MidFestivalMainQuestRewardVo
        rewardVo = nil,
        isLock = true,
        isGet = false
    }
    self.dialogId = Constants.UITypeIds.UIActivityMidFestivalStoryDialog
end

function ActivityMidFestivalRightNode:__delete()
    self.dialogId = nil
end

function ActivityMidFestivalRightNode:Awake()
    self:InitHandler()
    ---@type ActivityMidFestivalComponent
    self._activityMidFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
end

function ActivityMidFestivalRightNode:Start()

end

function ActivityMidFestivalRightNode:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
