--region init
function ActivityMidFestivalRightNode:InitHandler()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClickFontStyleButtonHandler))
end

---@param quest MidFestivalMainQuestLevelVo
function ActivityMidFestivalRightNode:InitData(quest)
    self.config.isLock = quest.status == 2
    self.config.isGet = quest.status == 0
    self.config.vo = quest
    ---@type MidFestivalMainQuestPlotVo
    self.episodeVo = CfUtils.GetCfVo(AutoIds.IdSetting6088, "MidFestivalMainQuestPlotVo", quest.id) -- 剧情表
    self.config.rewardVo = checkTable(ActivityMidFestivalMgr:LoadMainQuestRewardByQuestId(checkString(self.config.vo.id)))

    self.rewards = {}
    if next(self.config.rewardVo) ~= nil then
        for i, goodsId in ipairs(self.config.rewardVo.showItem) do
            local t = {
                goodsId = goodsId,
                num = self.config.rewardVo.showItemNum[i]
            }
            table.insert(self.rewards, t)
        end
    end

    self:RefreshUI()
end
--endregion init

--region handler
function ActivityMidFestivalRightNode:OnClickFontStyleButtonHandler()
    if self.config.vo.type == 1 then
        -- 纯剧情
        KCookie.Set(Constants.WayOfOpenMidFestivalMapKey, Constants.WayOfOpenMidFestivalMap.PLOT_OVER)
        ActivityMidFestivalMainQuestPlotTool.StartPlayPlot(self.episodeVo.plotIdStory, function()
            if not self.config.isGet then
                ActivityMidFestivalStoryTool.PlotOverReq(self.config.vo.id)
            end
        end)
    else
        KCookie.Set(Constants.WayOfOpenMidFestivalMapKey, Constants.WayOfOpenMidFestivalMap.BATTLE_OVER)
        if self.config.isGet then
            ActivityMidFestivalMainQuestPlotTool.StartPlayPlot(self.episodeVo.plotIdWave, function()
                ActivityMidFestivalMainQuestPlotTool.StartPlayPlot(self.episodeVo.plotIdEndWave)
            end)
            return
        end
        -- 开始战斗
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self.config.vo.id, activityUuid = self._activityMidFestivalComponent:GetActivityDojo().id } }, {
            { id = self.dialogId },
        })
    end
end
--endregion handler

--region public
---@param quest MidFestivalMainQuestLevelVo
function ActivityMidFestivalRightNode:Refresh(quest, purePlot, dialogId)
    self._purePlot = checkBool(purePlot)
    self.dialogId = dialogId
    self:InitData(quest)
end
--endregion public

--region private
function ActivityMidFestivalRightNode:RefreshRewards()
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsList , self.rewards)
end

function ActivityMidFestivalRightNode:RefreshUI()
    self:RefreshRewards()
    CfUtils.FillText(self.TextDesc, self.config.vo.desc)

    CfUtils.SetActive(self.RewardNode, not self._purePlot)

    if self._purePlot then
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
    else
        UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, self.config.vo.costItem, self.config.vo.costNum)
        CfUtils.SetActive(self.CommonBtnConsumePop, not self.config.isGet)
    end

    local fontStyleBtn = KTool.GetComponent(self.FontStyleButton.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    if self.config.isGet then
        fontStyleBtn:ResetFontStyle("B5" , localize("回顾剧情"))
        CfUtils.SetActive(self.FontStyleButton, self.config.vo.type ~= 0)
    else
        local btnName = self._purePlot and localize("阅读") or localize("前往战斗")
        fontStyleBtn:ResetFontStyle("B3" , btnName)
        CfUtils.SetActive(self.FontStyleButton, true)
    end
end
--endregion private

--region get / set
--endregion get / set

return ActivityMidFestivalRightNode
